(1,N'toolbelt_json',N'TVF_JsonPathExists','SELECT',N'SELECT * FROM toolbelt_json.TVF_JsonPathExists(N''{"a":1}'',N''$.a'');',N'DECLARE @Rows table(PathExists int NULL); DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{"a":1}'',N''$.a''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=1) THROW 52097,N''JSONPath fixed oracle 1.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{"a":null}'',N''$.a''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=1) THROW 52097,N''JSONPath fixed oracle 2.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{"a":1}'',N''$.missing''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=0) THROW 52097,N''JSONPath fixed oracle 3.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{"Name":1}'',N''$.name''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=0) THROW 52097,N''JSONPath fixed oracle 4.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{"key.with.dot":2}'',N''$."key.with.dot"'' ); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=1) THROW 52097,N''JSONPath fixed oracle 5.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{"items":[{}, {"value":null}]}'',N''$.items[*].value''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=1) THROW 52097,N''JSONPath fixed oracle 6.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{'',N''$.a''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=0) THROW 52097,N''JSONPath fixed oracle 7.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(N''{}'',N''$.a[''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists=0) THROW 52097,N''JSONPath fixed oracle 8.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(NULL,N''$.a''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists IS NULL) THROW 52097,N''JSONPath fixed oracle 9.'',12; DELETE @Rows; INSERT @Rows SELECT PathExists FROM toolbelt_json.TVF_JsonPathExists(REPLICATE(CONVERT(nvarchar(max),N''[''),129)+N''0''+REPLICATE(CONVERT(nvarchar(max),N'']''),129),N''$''); IF (SELECT COUNT(*) FROM @Rows)<>1 OR NOT EXISTS(SELECT 1 FROM @Rows WHERE PathExists IS NULL) THROW 52097,N''JSONPath fixed oracle 10.'',12; '),
